import java.util.*;

class Solution {
  public double[] medianSlidingWindow(int[] nums, int k) {
    // window indices ordered by value (index breaks ties), so dropping the outgoing element is O(log k),
    // unlike PriorityQueue.remove which is O(k)
    Comparator<Integer> byValue =
        (a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b);
    TreeSet<Integer> low = new TreeSet<>(byValue), high = new TreeSet<>(byValue); // low holds the extra one when k is odd
    double[] res = new double[nums.length - k + 1];
    for (int i = 0; i < nums.length; i++) {
      if (i >= k && !low.remove(i - k)) high.remove(i - k);
      low.add(i);
      high.add(low.pollLast());
      if (high.size() > low.size()) low.add(high.pollFirst());
      if (i >= k - 1)
        res[i - k + 1] =
            k % 2 == 1 ? nums[low.last()] : ((double) nums[low.last()] + nums[high.first()]) / 2.0;
    }
    return res;
  }
}
